metrics={c['rank']:c for c in json.load(open('judge-evidence/agreement.json')) if 86<=c['rank']<=110}
rows=[]; sections=[]
for rank,v in entries.items():
 c=metrics[rank]; urls=[f"https://oeis.org/{c['a']}",f"https://oeis.org/{c['b']}"]+v.get('extra',[])
 bmeta={}
 for aid in (c['a'],c['b']):
  p=Path(f'.firecrawl/{aid}-b.md')
  if p.exists():
   vals={int(m[1]):int(m[2]) for m in re.finditer(r'^(-?\d+)\s+(-?\d+)\s*$',p.read_text(),re.M)}
   if vals:bmeta[aid]=vals
 if len(bmeta)==2:
  a,b=bmeta.values(); start=max(min(a),min(b));end=min(max(a),max(b))
  mismatch=[{'n':i,'a':a[i],'b':b[i]} for i in range(start,end+1) if i in a and i in b and a[i]!=b[i]]
  extended={'start':start,'end_available':end,'first_mismatches':mismatch[:2]}
 else:extended=None
 row={'rank':rank,'a':c['a'],'b':c['b'],'verdict':'DROP','primary_gate':v['gate'],'agreement':v['agreement'],'novelty':v['novelty'],'integrity':v['integrity'],'metrics':c,'extended_bfile_comparison':extended,'sources':urls}
 rows.append(row)
 cites='; '.join(f'[{url.rsplit("/",1)[1]}]({url})' for url in urls)
 if len(bmeta)==2:
  cites+='; '+', '.join(f'[{aid} b-file](https://oeis.org/{aid}/b{aid[1:]}.txt)' for aid in bmeta)
 sections.append(f"## Candidate {rank}: {c['a']} vs {c['b']} — DROP ({v['gate']})\n\n**Agreement.** {v['agreement']}\n\n**Novelty.** {v['novelty']}\n\n**Integrity / reason.** {v['integrity']}\n\nSources: {cites}.\n")
Path('judge-evidence/reviews/86-110.json').write_text(json.dumps(rows,indent=2)+'\n')
Path('judge-evidence/reviews/86-110.md').write_text('\n'.join(sections))
print('Wrote',len(rows),'reviews; KEEP 0; DROP',len(rows),'; primary gates:',{g:sum(x['primary_gate']==g for x in rows) for g in {x['primary_gate'] for x in rows}})
